Steps:
[AUTH role=ADMIN_DEFAULT]
[GQL-OP wl]
query {
  whiteLabelingSettings(organizationId: "{{org_id}}" storeId: "{{STORE_ID}}" cultureName: "en-US") {
    footerLinks { title url priority childItems { title url priority } }
    mainMenuLinks { title url priority childItems { title url priority } }
  }
}
[GQL-EXEC wl]

Assertions:
[ERRORS label=wl] errors[] empty
[COUNT label=wl] data.whiteLabelingSettings.footerLinks[?title=Legal].childItems.length = 2
[DATA label=wl] data.whiteLabelingSettings.footerLinks[?title=Legal].priority = {{p_legal}}
[DATA label=wl] data.whiteLabelingSettings.footerLinks[?title=Help].priority = {{p_help}}
[DATA label=wl] data.whiteLabelingSettings.mainMenuLinks[?title=Home].priority = {{p_home}}
[DATA label=wl] data.whiteLabelingSettings.mainMenuLinks[?title=Support].priority = {{p_support}}
[DATA label=wl] data.whiteLabelingSettings.mainMenuLinks[?title=Brands].priority = {{p_brands}}
[COUNT label=wl] data.whiteLabelingSettings.mainMenuLinks[?title=Brands].childItems.length = 3
[DATA label=wl] data.whiteLabelingSettings.mainMenuLinks[?title=Brands].childItems[?title=Laptops].priority = {{p_laptops}}

